class C {
 public static string Name;
 public static string Label { get; }
 static C() {
  Name = "Ada";
  if (Name == "Ada") { Label = "yes"; return; }
  Label = "no";
 }
 public static string Read() => Name + ":" + Label;
}
void Main() { Print(C.Read()); C.Name = "Grace"; Print(C.Read()); }
